// MenuButton — Gtk.MenuButton
//
// Generated by bin/11-generate-components, which does not overwrite.
//
// It ships no template, so the markup is the one element its CSS node is, carrying what
  // Adwaita styles menubutton with.

import type { ReactNode } from "react"

import { cn } from "@/lib/utils"
import type { WidgetProps } from "@/lib/widget-props"
import type { ArrowType } from "@/lib/enums"

export interface MenuButtonProps extends WidgetProps {
  className?: string
  children?: ReactNode
  /** gboolean, from Gtk.MenuButton */
  active?: boolean

  /** gboolean, from Gtk.MenuButton */
  alwaysShowArrow?: boolean

  /** gboolean, from Gtk.MenuButton */
  canShrink?: boolean

  /** Widget, from Gtk.MenuButton */
  child?: ReactNode

  /** ArrowType, from Gtk.MenuButton */
  direction?: ArrowType

  /** gboolean, from Gtk.MenuButton */
  hasFrame?: boolean

  /** utf8, from Gtk.MenuButton */
  iconName?: string

  /** utf8, from Gtk.MenuButton */
  label?: string

  /** Gio.MenuModel, from Gtk.MenuButton */
  menuModel?: ReactNode

  /** Popover, from Gtk.MenuButton */
  popover?: ReactNode

  /** gboolean, from Gtk.MenuButton */
  primary?: boolean

  /** gboolean, from Gtk.MenuButton */
  useUnderline?: boolean
}

export function MenuButton({ className, children, label }: MenuButtonProps) {
  return (
    <div className={cn(className)}>
      {label}
      {children}
    </div>
  )
}
